using Diten.DecisionIntelligenceService.Application.Modules.OutcomeTracking;
using Diten.DecisionIntelligenceService.Domain.Modules.OutcomeTracking;
using Xunit;

public class DomainTests
{
 static readonly Guid T=Guid.NewGuid(),O=Guid.NewGuid(),V=Guid.NewGuid(),A=Guid.NewGuid();
 static OutcomeMeasurement M(Guid id,MeasurementPeriod p,Guid? s=null,OutcomeKind k=OutcomeKind.Quantitative,decimal? value=1,string? level=null)=>new(id,T,O,V,k,p,value,level,s,s is null?null:CorrectionReason.DataCorrection,A);
 [Fact] public void Period_is_half_open_and_bounded(){var today=new DateOnly(2026,8,5);new MeasurementPeriod(today.AddDays(-366),today).Validate(today);Assert.Throws<ArgumentException>(()=>new MeasurementPeriod(today,today).Validate(today));Assert.Throws<ArgumentException>(()=>new MeasurementPeriod(today.AddDays(-367),today).Validate(today));Assert.Throws<ArgumentException>(()=>new MeasurementPeriod(today,today.AddDays(2)).Validate(today));Assert.Throws<ArgumentException>(()=>new MeasurementPeriod(today.AddYears(-11),today).Validate(today));Assert.False(new MeasurementPeriod(today,today.AddDays(1)).Overlaps(new(today.AddDays(1),today.AddDays(2))));}
 [Fact] public void Overlap_and_branch_fail_closed(){var p=new MeasurementPeriod(new(2026,1,1),new(2026,2,1));var first=M(Guid.NewGuid(),p);Assert.Throws<DomainConflictException>(()=>MeasurementRules.NoOverlap([first],M(Guid.NewGuid(),p)));var c=M(Guid.NewGuid(),p,first.Id);MeasurementRules.CorrectionHead([first],c);Assert.Throws<DomainConflictException>(()=>MeasurementRules.CorrectionHead([first,c],M(Guid.NewGuid(),p,first.Id)));}
 [Fact] public void Self_and_mixed_payload_are_rejected(){var id=Guid.NewGuid();var p=new MeasurementPeriod(new(2026,1,1),new(2026,2,1));Assert.Throws<ArgumentException>(()=>M(id,p,id));Assert.Throws<ArgumentException>(()=>new OutcomeMeasurement(Guid.NewGuid(),T,O,V,OutcomeKind.Quantitative,p,1,"level",null,null,A));}
 [Fact] public void Metric_bounds_scale_currency_are_exact(){new OutcomeMetricVersion(Guid.NewGuid(),T,Guid.NewGuid(),1,UnitKind.Percentage,null,0.0000m,100.0000m,30).Validate().ValidateValue(10.1234m);Assert.Throws<ArgumentException>(()=>new OutcomeMetricVersion(Guid.NewGuid(),T,Guid.NewGuid(),1,UnitKind.Percentage,null,-1,100,30).Validate());Assert.Throws<ArgumentException>(()=>new OutcomeMetricVersion(Guid.NewGuid(),T,Guid.NewGuid(),1,UnitKind.Currency,null,0,1,30).Validate());Assert.Throws<ArgumentException>(()=>new OutcomeMetricVersion(Guid.NewGuid(),T,Guid.NewGuid(),1,UnitKind.Count,null,0,10,30).ValidateValue(1.12345m));}
 [Fact] public void Scale_membership_is_ordinal_and_case_sensitive(){var s=new QualitativeScaleVersion(Guid.NewGuid(),T,Guid.NewGuid(),1,[new("low",1,"Low"),new("high",2,"High")]);s.ValidateLevel("low");Assert.Throws<ArgumentException>(()=>s.ValidateLevel("LOW"));Assert.Throws<ArgumentException>(()=>new QualitativeScaleVersion(Guid.NewGuid(),T,Guid.NewGuid(),1,[new("x",1,"X"),new("x",2,"Y")]));}
 [Fact] public void Versions_are_monotonic_and_kind_reference_is_exclusive(){var o=new Outcome(O,T,"O","Outcome",OutcomeKind.Quantitative,A);var mr=new MetricReferenceV1(MetricReferenceV1.Name,"1.0",Guid.NewGuid(),Guid.NewGuid(),1);o.Publish(new(Guid.NewGuid(),T,O,1,OutcomeKind.Quantitative,mr,null,A));Assert.Throws<DomainConflictException>(()=>o.Publish(new(Guid.NewGuid(),T,O,3,OutcomeKind.Quantitative,mr,null,A)));Assert.Throws<ArgumentException>(()=>new OutcomeVersion(Guid.NewGuid(),T,O,2,OutcomeKind.Qualitative,mr,null,A));}
}
